CREATE TABLE ibexa_token (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, type_id INTEGER NOT NULL, token VARCHAR(255) NOT NULL, identifier VARCHAR(128) DEFAULT NULL, created INTEGER DEFAULT 0 NOT NULL, expires INTEGER DEFAULT 0 NOT NULL, revoked BOOLEAN DEFAULT '0' NOT NULL, CONSTRAINT ibexa_token_type_id_fk FOREIGN KEY (type_id) REFERENCES ibexa_token_type (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
